select.if:
SELECT ID, text, "object" FROM ( SELECT COUNTER_ID ID, COUNTER_NAME text, CASE WHEN T2.CUSTOMER_ID IS NOT NULL THEN 'S' WHEN COUNTER_TYPE = '05' THEN 'N' ELSE 'Y' END "object" FROM MST_COUNTER_PARTY T1 LEFT JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID
AND not exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = T1.COUNTER_ID) and NOT EXISTS (SELECT 1 FROM fin_product p WHERE p.FINPROD_MARKET_ID = T1.COUNTER_ID)
AND exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = T1.COUNTER_ID AND P.INVEST_YESORNO = 'Y')
AND ( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND T1.COUNTER_TYPE = #{counterType}
) T WHERE T ."object" <> 'N' UNION SELECT T1.COUNTER_ID ID, T1.COUNTER_NAME text, CASE WHEN T2.CUSTOMER_ID IS NOT NULL THEN 'S' WHEN T1.COUNTER_TYPE = '05' THEN 'N' ELSE 'Y' END "object" FROM MST_COUNTER_PARTY T1 LEFT JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID WHERE T1.COUNTER_ID IN ( SELECT P .FINPROD_MARKET_ID FROM FIN_PRODUCT P LEFT JOIN FIN_PRODUCT_ADD PADD ON P .FINPROD_ID = PADD.FINPROD_ID WHERE PADD.PROD_MANAGER = ( SELECT DISTINCT PROD_MANAGER FROM FIN_PRODUCT_ADD YADD WHERE YADD.PORTFOLIO_ID = #{pfId} ) )
AND not exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = T1.COUNTER_ID) and NOT EXISTS (SELECT 1 FROM fin_product p WHERE p.FINPROD_MARKET_ID = T1.COUNTER_ID)
AND exists (select 1 from PTL_PORTFOLIO p where p.PORTFOLIO_ID = T1.COUNTER_ID AND P.INVEST_YESORNO = 'Y')
AND ( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND T1.COUNTER_TYPE = #{counterType}

UNION SELECT COUNTER_ID id, COUNTER_NAME text, CASE WHEN T2.CUSTOMER_ID IS NOT NULL THEN 'S' WHEN COUNTER_TYPE=#{COUNTER_TYPE} THEN #{YES_NO_N} ELSE #{YES_NO_Y} END "object" FROM MST_COUNTER_PARTY T1 LEFT JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID
AND ( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND COUNTER_ID = #{COUNTER_PARTY_ID_SHANGHAI}
AND COUNTER_ID = #{COUNTER_PARTY_ID_SHENZHEN}

mapper.select:
SELECT T1.COUNTER_ID id, T1.COUNTER_NAME text, 'S' "object" FROM MST_COUNTER_PARTY T1 INNER JOIN MST_CUSTOMER_INFO T2 ON T1.LINK_ID = T2.CUSTOMER_ID
AND ( T1.COUNTER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR T1.COUNTER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND T1.COUNTER_ID = #{initValue}
AND T1.COUNTER_TYPE = #{counterType}

SELECT USER_NAME id, REAL_NAME text FROM SYS_USER WHERE 1 =1
AND ( USER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) OR REAL_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND USER_NAME = #{initValue}

SELECT TRADER_ID id, TRADER_NAME text FROM MST_CFETS_CUSTOMER_TRADER WHERE 1=1
AND ( TRADER_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR TRADER_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND TRADER_ID = #{initValue}
